	private void assertReplayCancellation(Path dataDir, boolean queued) throws Exception {
		AtomicReference<Thread> replayThread = new AtomicReference<>();
		CountDownLatch submitted = new CountDownLatch(1);
		AtomicInteger submissions = new AtomicInteger();
		LmdbStore store = new LmdbStore(dataDir.toFile(), new LmdbStoreConfig()
				.setMapGrowthReadDrainTimeoutMillis(100)) {
			@Override
			LmdbSailStore createBackingStore(File directory, StoreProperties properties, LmdbStoreConfig config,
					boolean sketchBasedJoinEstimatorEnabled) throws IOException {
				return new LmdbSailStore(directory, properties, config, sketchBasedJoinEstimatorEnabled) {
					@Override
					Future<?> submitReplayRetirement(Runnable retirement) {
						boolean connectionReplay = submissions.incrementAndGet() == (queued ? 5 : 1);
						Future<?> result = super.submitReplayRetirement(() -> {
							if (connectionReplay) {
								replayThread.set(Thread.currentThread());
							}
							retirement.run();
						});
						if (connectionReplay) {
							submitted.countDown();
						}
						return result;
					}
				};
			}
		};
		store.init();
		LmdbSailStore backing = store.getBackingStore();
		Object writerOwner = new Object();
		try (var executor = Executors.newFixedThreadPool(2);
				LmdbStoreConnection connection = (LmdbStoreConnection) store.getConnection();
				LmdbSailStore.ReadAttemptLease writer = backing.registerReadAttempt(writerOwner,
						(kind, token, deadline, attempts, views) -> false)) {
			connection.begin(IsolationLevels.SNAPSHOT);
			try (var result = connection.getStatements(null, null, null, false)) {
				writer.markWriteIntent();
				try (LmdbSailStore.MapGrowthAttempt warning = backing.beginMapGrowthWarning(writerOwner);
						LmdbSailStore.MapGrowthAttempt growth = backing.beginMapGrowthAttempt(writerOwner)) {
					List<Future<?>> otherRetirements = new ArrayList<>();
					if (queued) {
						// Occupy the store's four retirement workers with genuine waits owned by other connections.
						for (int i = 0; i < 4; i++) {
							AtomicReference<Thread> otherThread = new AtomicReference<>();
							otherRetirements.add(backing.submitReplayRetirement(() -> {
								otherThread.set(Thread.currentThread());
								backing.awaitGrowthEnd(growth.token());
							}));
							awaitWaitingIn(otherThread, "awaitGrowthEnd");
						}
					}
					var requesting = executor.submit(() -> {
						growth.requestQuiescence(LmdbSailStore.MapResizeKind.TRIPLE_STORE);
						return null;
					});
					Future<?> closing;
					try {
						assertTrue(submitted.await(5, TimeUnit.SECONDS));
						if (!queued) {
							awaitWaitingIn(replayThread, "awaitGrowthEnd");
						}
						result.close();
						closing = executor.submit(connection::close);
						closing.get(2, TimeUnit.SECONDS);
						for (Future<?> other : otherRetirements) {
							assertFalse(other.isDone(), "Cancelling one connection must not cancel other retirements");
						}
					} finally {
						growth.close();
						warning.close();
						writer.completeTransaction();
					}
					closing.get(5, TimeUnit.SECONDS);
					requesting.get(5, TimeUnit.SECONDS);
					for (Future<?> other : otherRetirements) {
						other.get(5, TimeUnit.SECONDS);
					}
				}
			}
		} finally {
			store.shutDown();
		}
	}

	@Test
	void interruptedFinalizationRejectsQueuedCapturedWorkBeforeDraining(@TempDir Path dataDir) throws Exception {
		LmdbStore store = new LmdbStore(dataDir.toFile()) {
			@Override
			protected NotifyingSailConnection getConnectionInternal() {
				return new CapturingConnection(this);
			}
		};
		store.init();
		CountDownLatch entered = new CountDownLatch(1);
		CountDownLatch cancelled = new CountDownLatch(1);
		CountDownLatch releaseCleanup = new CountDownLatch(1);
		AtomicReference<Thread> finalizer = new AtomicReference<>();
		try (var executor = Executors.newFixedThreadPool(2);
				CapturingConnection connection = (CapturingConnection) store.getConnection()) {
			connection.begin(IsolationLevels.SNAPSHOT);
			QueryExecutionContext.ReplayContext context = connection.captureReadContext();
			assertNotNull(context);
			var worker = executor.submit(() -> context.run(() -> {
				entered.countDown();
				try {
					assertTrue(releaseCleanup.await(5, TimeUnit.SECONDS));
				} catch (InterruptedException expected) {
					cancelled.countDown();
					assertThrows(SailException.class, connection::executeNestedRead);
					assertThrows(SailException.class, () -> connection.captureReadContext().run(() -> {
						throw new AssertionError("Catching interruption must not renew a nested read's authority");
					}));
					try {
						assertTrue(releaseCleanup.await(5, TimeUnit.SECONDS));
					} catch (InterruptedException failure) {
						throw new AssertionError("Cleanup should only be cancelled once", failure);
					} finally {
						Thread.currentThread().interrupt();
					}
				}
			}));
			assertTrue(entered.await(5, TimeUnit.SECONDS));
			var finishing = executor.submit(() -> {
				finalizer.set(Thread.currentThread());
				try {
					connection.prepare();
				} catch (InterruptedSailException expected) {
					// Publication may reject the restored interrupted status after safe read retirement.
				}
				return Thread.interrupted();
			});
			try {
				awaitWaitingIn(finalizer, "finishReadAttempt");
				finalizer.get().interrupt();
				assertTrue(cancelled.await(2, TimeUnit.SECONDS));
				assertThrows(SailException.class, () -> context.run(() -> {
					throw new AssertionError("Cancelled captured work must not be activated during native drain");
				}));
			} finally {
				releaseCleanup.countDown();
			}
			worker.get(5, TimeUnit.SECONDS);
			assertTrue(finishing.get(5, TimeUnit.SECONDS));
		} finally {
			releaseCleanup.countDown();
			store.shutDown();
		}
	}

	private static final class CapturingConnection extends LmdbStoreConnection {
		private CapturingConnection(LmdbStore store) {
			super(store);
		}

		private QueryExecutionContext.ReplayContext captureReadContext() {
			return executeReadOperation(QueryExecutionContext::captureReplayContext);
		}

		private void executeNestedRead() {
			executeReadOperation(() -> {
				throw new AssertionError("Cancelled outer admission must not authorize a nested native operation");
			});
		}
	}

